-- Schema completo da DeSanti Automotiva para PostgreSQL / Supabase
-- Executar no SQL Editor do Supabase antes de iniciar a API em produção.

CREATE TABLE IF NOT EXISTS "Clientes" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nome" varchar(200) NOT NULL,
    "Email" varchar(200) NOT NULL DEFAULT '',
    "Telefone" varchar(20) NOT NULL,
    "Documento" varchar(20) NULL,
    "DataCriacao" timestamp with time zone NOT NULL,
    "DataAlteracao" timestamp with time zone NULL,
    "Ativo" boolean NOT NULL DEFAULT TRUE
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_clientes_documento" ON "Clientes" ("Documento");
CREATE INDEX IF NOT EXISTS "idx_clientes_nome" ON "Clientes" ("Nome");


CREATE TABLE IF NOT EXISTS "OrdensServico" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ClienteId" bigint NOT NULL,
    "NomeCliente" varchar(200) NOT NULL,
    "DocumentoCliente" varchar(20) NOT NULL,
    "TelefoneCliente" varchar(20) NOT NULL,
    "Placa" varchar(7) NOT NULL,
    "Marca" varchar(100) NOT NULL,
    "Modelo" varchar(100) NOT NULL,
    "Cor" varchar(50) NOT NULL,
    "Ano" integer NULL,
    "DescricaoServico" text NOT NULL,
    "MaoDeObraCentavos" bigint NOT NULL,
    "TotalCentavos" bigint NOT NULL,
    "NecessitaRetorno" boolean NOT NULL,
    "PrazoRetornoDias" integer NULL,
    "DataCriacaoUtc" timestamp with time zone NOT NULL,
    "DataConclusaoUtc" timestamp with time zone NULL,
    "DataPrevistaRetornoUtc" timestamp with time zone NULL,
    "Status" integer NOT NULL DEFAULT 1,
    "IdempotencyKey" varchar(64) NULL,
    CONSTRAINT "FK_OrdensServico_Clientes_ClienteId" FOREIGN KEY ("ClienteId")
        REFERENCES "Clientes" ("Id") ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS "IX_OrdensServico_ClienteId" ON "OrdensServico" ("ClienteId");
CREATE INDEX IF NOT EXISTS "IX_OrdensServico_Placa" ON "OrdensServico" ("Placa");
CREATE INDEX IF NOT EXISTS "IX_OrdensServico_Status" ON "OrdensServico" ("Status");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_ordens_servico_idempotency_key" ON "OrdensServico" ("IdempotencyKey");


CREATE TABLE IF NOT EXISTS "PecasOrdemServico" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OrdemServicoId" bigint NOT NULL,
    "Nome" varchar(200) NOT NULL,
    "Quantidade" integer NOT NULL,
    "ValorUnitarioCentavos" bigint NOT NULL,
    "ValorTotalCentavos" bigint NULL,
    "CustoUnitarioCentavos" bigint NULL,
    CONSTRAINT "FK_PecasOrdemServico_OrdensServico_OrdemServicoId" FOREIGN KEY ("OrdemServicoId")
        REFERENCES "OrdensServico" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_PecasOrdemServico_OrdemServicoId" ON "PecasOrdemServico" ("OrdemServicoId");


CREATE TABLE IF NOT EXISTS "Usuarios" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "NomeUsuario" varchar(64) NOT NULL,
    "Nome" varchar(120) NOT NULL,
    "Email" varchar(200) NULL,
    "PasswordHash" varchar(256) NOT NULL,
    "Role" varchar(32) NOT NULL,
    "Ativo" boolean NOT NULL DEFAULT TRUE,
    "DataCriacaoUtc" timestamp with time zone NOT NULL,
    "DataAlteracaoUtc" timestamp with time zone NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_usuarios_nome_usuario" ON "Usuarios" ("NomeUsuario");


CREATE TABLE IF NOT EXISTS "KeepAwakeRecords" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Status" smallint NOT NULL DEFAULT 1,
    "UpdatedAtUtc" timestamp with time zone NOT NULL
);
